import * as Orders from './supply-orders.js';
import * as Goods from './supplies.js';
import * as Review from './record-review.js';
import * as M from './model.js';
import * as A from './academic-year.js';
import * as Staff from './staff-work.js';
import * as Support from './student-support.js';
import * as Ops from './school-operations.js';
import * as Career from './career.js';
import * as People from './community-life.js';
import * as Detail from './school-review.js';
export function createWorkUI(h){const {get,esc,q,val,num,btn,text,field,select,dates,open,outcome,ctx}=h;const studentSelect=id=>select(id,get().students.map(st=>[st.id,st.name]));const roomSelect=(id,value='classroom')=>select(id,Object.entries(M.ROOMS).map(([id,r])=>[id,r.name]),value);const history=rows=>`<div class="beta-history">${rows.map(r=>`<p>${esc(r.date||'')} · ${esc(r.label||r.status||r.step||'')} ${esc(r.text||r.reason||'')}</p>`).join('')}</div>`;
 function staff(){const s=get(),d=Staff.data(s),p=Staff.project(s),a=Staff.audit(s);open('학교 행정·교사 개인 업무',`<div class="work-section-banner administrative"><b>학급업무와 구분한 교사 업무</b><span>연수 · 출장 · 선도사업 · 협의와 감사</span></div><div class="buttons">${btn('스킬·업무 세부','beta-operations-detail')}${btn('위원 선출·봉사 일정','beta-governance')}${btn('법정·직무 연수','beta-training')}${btn('특별실·전담 협의','beta-reservations')}${btn('기물 수리','beta-maintenance')}${btn('공문·회의록','computer')}${btn('업무분장 계획','work-plans')}</div><h4>선도사업 · ${p.topic}</h4><p>${p.selected?'지정 기간 운영 중':'지정 기간 종료'} · 실제 관련 수업 ${p.lessons}/${p.required}차시 · ${p.shared?'결과 공유 완료':'결과 미공유'}</p>${field('우리 반 운영 목표',text('bw-project',p.goal))}${btn('목표 저장','beta-project-plan')}${field('운영 결과와 다음 개선점',text('bw-project-report'))}${btn('실제 수업 근거로 공유 · 20분','beta-project-share')}<p class="intro">수업 준비 화면에서 이 사업을 연결한 수업을 직접 진행해야 횟수가 올라갑니다.</p><h4>교육청 감사 · 학교별 ${a.school.auditCycle}년 주기</h4><p>최근 ${a.school.lastAudit}년 · 다음 ${a.due}년 · ${a.current?(a.current.done?'후속 확인 완료':['자료 확인','요청 자료·담임 소관 분류','확인 내용·보완','후속 점검'][a.current.stage]):'진행 중 감사 없음'}</p>${a.current&&!a.current.done?`${field('담임 소관의 실제 근거와 확인 내용',text('bw-audit'))}${btn('감사 단계 기록 · 20분','beta-audit-step')}`:''}<h4>방과 후 출장</h4><div class="beta-grid">${field('출장 제목','<input id="bw-trip-title" placeholder="교육지원청 수업 나눔">')}${field('출장일',dates('bw-trip-day'))}${field('출발',select('bw-trip-start',[[900,'15:00'],[910,'15:10'],[920,'15:20']]))}${field('복귀',select('bw-trip-end',[[980,'16:20'],[990,'16:30'],[1000,'16:40']],1000))}</div>${btn('출장 신청','beta-business-request')}${d.business.map(t=>`<article class="beta-card"><b>${esc(t.title)}</b><p>${M.dateLabel({day:t.day})} ${M.clock(t.start)}–${M.clock(t.end)} · ${esc(t.status)}</p>${t.status==='requested'?btn('담당 인계 확인·관리자 승인','beta-business-approve',`data-id="${t.id}"`):t.status==='approved'?btn('담당자 인계 후 출발','beta-business-depart',`data-id="${t.id}"`):t.status==='on-site'?`${text('bw-report-'+t.id,'','현장 확인 내용과 학교에 공유할 점')}${btn('출장 결과 기록·복귀','beta-business-return',`data-id="${t.id}"`)}`:t.report?`<p>${esc(t.report)}</p>`:''}${['requested','approved'].includes(t.status)?btn('취소','beta-business-cancel',`data-id="${t.id}"`):''}</article>`).join('')}<h4>학교 협의·조직</h4><div class="beta-grid">${field('협의체',select('bw-committee',['부장회의','학교운영위원회']))}${field('참여 방식',select('bw-vote',[['','자료·의견 전달'],['찬성','찬성'],['보완','보완 의견']]))}</div>${field('안건에 대한 의견',text('bw-opinion'))}${btn('참여 기록 · 20분','beta-committee')}<p class="intro">부장회의는 부장 역할, 학교운영위원회 표결은 별도 선출된 위원 자격에서만 가능합니다. 일반 담임은 학급 의견과 자료를 전달합니다.</p><div class="buttons">${btn('학부모회 자율 참여 안내','beta-parent-org','data-id="학부모회"')}${btn('등하교 안전 봉사 희망 확인','beta-parent-org','data-id="녹색어머니회"')}</div>${d.organizations.map(o=>`<p>${esc(o.kind)} · 자율 희망 ${o.volunteers.length}가정 · ${o.date}</p>`).join('')}<h4>교직원 식사 모임</h4><p>수업 후 동료와 짧게 안부를 나눕니다. 불참·조기 귀가는 관계나 평가의 불이익이 없습니다.</p><div class="buttons">${btn('참석 · 30분','beta-social','data-id="join"')}${btn('잠깐 인사 · 10분','beta-social','data-id="early"')}${btn('이번에는 불참','beta-social','data-id="decline"')}</div>`);}
 function training(id){const s=get(),t=Staff.trainingStatus(s,id);if(t){const c=t.course;open(c.name,`<p class="intro">게임의 가상 연수입니다. 실제 이수증을 발급하지 않습니다. 적용 대상·시간·주기는 학교의 해당 연도 지침에서 확인하는 구조입니다.</p><div class="notice">이론 ${t.theory}/${c.hours-c.practice}시간 · 실습 ${t.practice}/${c.practice}시간 · ${t.complete?'충족':'진행 중'}<p>${c.cycle===.5?'학기별':c.cycle+'년 주기'} · 각 모듈은 게임 시간 60분</p></div><h4>${c.question}</h4>${field('수강 형태',select('bw-practice',[['0','원격 이론'],...(c.practice?[['1','전문 강사와 집합 실습']]:[])]))}<div class="choice-list">${[c.yes,c.no].map((line,i)=>btn(line,'beta-train',`data-id="${id}" data-choice="${i}" ${t.complete?'disabled':''}`)).join('')}</div>${btn('전체 연수 현황','beta-training')}${history(Staff.data(s).training.filter(x=>x.courseId===id).map(x=>({...x,text:(x.practice?'실습':'이론')+' 1시간'})))}`);return;}open('교사 연수 대장',`<p class="intro">이론·실습과 유효 기간을 따로 기록합니다. 수업이나 회의와 겹치는 수강은 막습니다.</p><div class="beta-course-list">${Staff.COURSES.map(c=>{const t=Staff.trainingStatus(s,c.id);return `<article><span><b>${c.name}</b><small>${c.cycle===.5?'학기마다':c.cycle+'년 주기'} · ${t.theory+t.practice}/${c.hours}시간 · ${c.practice?'실습 '+t.practice+'/'+c.practice:'이론'}</small></span>${btn(t.complete?'이수 기록':'수강','beta-training',`data-id="${c.id}"`)}</article>`;}).join('')}</div>`);}
 function support(id){const s=get(),d=Support.data(s),c=d.cases.find(x=>x.id===id);if(c){const st=s.students.find(x=>x.id===c.studentId)||People.former(s,c.studentId),steps=Support.STEPS[c.kind];open(st.name+' · '+Support.KINDS[c.kind],`<div class="beta-row">${ctx.portrait(st.id,'lg')}<span><b>${st.name}</b><small>${esc(st.supportInfo?.needs)}</small></span></div><div class="notice">${esc(c.observation)}</div><div class="beta-steps">${steps.map((t,i)=>`<span class="${i===c.step?'current':''}">${i+1}. ${t}${i<c.step?' ✓':''}</span>`).join('')}</div>${c.closed?'<p class="tag">지원·후속 확인 완료</p>':`${field('이번에 확인한 사실·학생의 말·지원 방법',text('bs-note'))}${c.kind==='health'&&c.step===3?`${btn('보호자·보건교사 복귀 자료 확인','beta-clearance',`data-id="${id}"`)}<p>${c.clearance?'복귀 가능 안내 확인됨':'복귀 확인 전 · 자동 복귀하지 않음'}${c.health?' · 확인 자료: '+c.health:''}</p>`:''}<div class="buttons">${btn(c.kind==='health'&&c.step===2?'보호자의 확인 자료 접수':c.kind==='disruption'&&c.step===3?'담당자 확보·학습 지원 연결':'지원·협의 이어가기','beta-support-act',`data-id="${id}" data-choice="0"`,'primary')}${btn(c.kind==='health'&&c.step===2?'병명 미확인·귀가 인계':c.kind==='disruption'?'교실에서 대안·참여 지원':'학생의 의사를 듣고 조정','beta-support-act',`data-id="${id}" data-choice="1"`)}</div>`}${history(c.history)}${btn('학생 지원 대장','beta-support')}`);return;}open('학생 지원·생활지도',`<p class="intro">관찰 사실, 학생의 말, 지원 담당자를 구분해 기록합니다. 배경이나 진단 이름은 능력 수치나 문제 행동의 원인으로 사용하지 않습니다.</p><div class="buttons">${btn('출결 서류 접수·확인','beta-forms')}${btn('대회·탐구 프로젝트','beta-contests')}${btn('행동특성 문장 검토','beta-review')}${btn('전교 선거·학생회','beta-council')}</div><div class="beta-grid">${field('학생',studentSelect('bs-student'))}${field('지원 종류',select('bs-kind',Object.entries(Support.KINDS)))}</div>${field('관찰한 상황',text('bs-observation','','언제·어디서·무엇을 보거나 들었는지'))}${btn('지원 기록 열기','beta-support-open','','primary')}<div class="beta-event-list">${d.cases.map(c=>`<div><span><b>${(s.students.find(x=>x.id===c.studentId)||People.former(s,c.studentId))?.name}</b> · ${Support.KINDS[c.kind]}<small>${c.closed?'완료':Support.STEPS[c.kind][c.step]} · ${c.date}</small></span>${btn('이어 보기','beta-support',`data-id="${c.id}"`)}</div>`).join('')||'<p>아직 지원 기록이 없습니다.</p>'}</div>`);}
 function forms(id){const s=get(),d=Support.data(s),f=d.documents.find(x=>x.id===id);if(f){const st=s.students.find(x=>x.id===f.studentId)||People.former(s,f.studentId);open(st.name+' · 출결 서류',`<div class="notice"><b>${{family:'교외체험학습',home:'가정학습',absence:'결석계'}[f.kind]}</b><p>${M.dateLabel({day:f.from})} ~ ${M.dateLabel({day:f.to})} · ${f.channels.join('·')}<br>처리: ${f.stage}</p></div><p>${esc(f.detail)}</p><p>확인 자료: ${esc(f.evidence||'미제출')}</p>${field('확인 내용·보완 사유·보고서',text('bf-note'))}<div class="buttons">${btn('보완 요청','beta-doc-revise',`data-id="${id}" ${f.stage!=='received'?'disabled':''}`)}${btn('자료 확인·승인','beta-doc-approve',`data-id="${id}" ${f.stage!=='received'?'disabled':''}`)}${btn('실시 후 보고서 접수','beta-doc-report',`data-id="${id}" ${f.stage!=='approved'?'disabled':''}`)}${btn('보고서 확인·종결','beta-doc-close',`data-id="${id}" ${f.stage!=='reported'?'disabled':''}`)}</div>${f.stage==='revision'?`${field('보완한 신청 내용',text('bf-revised',f.detail))}${field('보완한 확인 자료',text('bf-evidence',f.evidence))}${btn('보완 서류 다시 접수','beta-doc-resubmit',`data-id="${id}"`)}`:''}${history(f.history)}${btn('서류 목록','beta-forms')}`);return;}open('가정체험학습·결석계',`<p class="intro">앱·종이로 중복 제출되어도 같은 학생·종류·기간은 한 건으로 묶습니다. 신청 → 보완/승인 → 실시 → 보고 → 확인 순서입니다.</p><div class="notice">가상 학교 예시: 체험학습 ${d.rules.familyLeadDays}등교일 전 신청 · 실시 후 ${d.rules.familyReportDays}등교일 이내 보고 안내 · 가정학습 ${d.rules.homeStudy?'허용':'미허용'}. 실제 지역별 기한과 다를 수 있습니다.</div><div class="beta-grid">${field('학생',studentSelect('bf-student'))}${field('종류',select('bf-kind',[['family','가정 동반 교외체험학습'],['home','가정학습'],['absence','결석계']]))}${field('시작',select('bf-from',s.academic.calendar.filter(d=>d.school).map(d=>[d.day,M.dateLabel({day:d.day})]),s.day))}${field('끝',select('bf-to',s.academic.calendar.filter(d=>d.school).map(d=>[d.day,M.dateLabel({day:d.day})]),s.day))}${field('접수 경로',select('bf-channel',['앱','종이']))}${field('결석 구분',select('bf-absence',['질병결석','기타결석','인정결석']))}</div>${field('보호자가 제출한 계획·사유',text('bf-detail'))}${field('제출된 확인 자료 요약',text('bf-evidence','','게임 속 확인 자료의 종류·범위'))}${btn('가상 보호자 서류 접수','beta-doc-submit','','primary')}<div class="beta-event-list">${d.documents.map(f=>`<div><span>${(s.students.find(x=>x.id===f.studentId)||People.former(s,f.studentId))?.name} · ${{family:'체험학습',home:'가정학습',absence:'결석계'}[f.kind]}<small>${M.dateLabel({day:f.from})} · ${f.stage}${f.dueStatus?' · '+f.dueStatus:''}</small></span>${btn('처리','beta-forms',`data-id="${f.id}"`)}</div>`).join('')}</div>`);}
 function reservations(){const s=get();open('특별실 예약·시간표 협의',`<p class="intro">학교교육과정이 제시한 날짜별 시간표를 바탕으로 협의합니다. 시작한 수업·고정 행사는 바꿀 수 없습니다. 편성 변경 후 학교교육과정의 시수와 학급교육과정 이수부를 확인하세요.</p><div class="beta-grid">${field('날짜',dates('br-day'))}${field('교시',select('br-period',[1,2,3,4,5,6]))}${field('과목',select('br-subject',[...M.subjects(s.config.grade),'창체']))}${field('장소',roomSelect('br-room'))}</div>${btn('해당 수업의 특별실 예약','beta-reserve')}<h4>수업 변경 협의</h4>${field('변경 사유',text('br-reason'))}<div class="buttons">${btn('위 날짜·교시를 선택 과목으로 변경','beta-lesson-change')}${btn('전담 결강 · 담임 대체 협의','beta-specialist-cover')}${btn('학교 안내에 따라 해당 일 휴업','beta-closure')}</div><p class="intro">전담 결강 대체는 전담교사에게 관찰을 인계하며, 같은 시수를 두 번 올리지 않습니다.</p><div class="beta-event-list">${s.academic.reservations.filter(r=>!r.cancelled).map(r=>`<div><span>${M.dateLabel({day:r.day})} ${r.period}교시 · ${r.subject}<small>${M.ROOMS[r.room].name}</small></span>${btn('예약 취소','beta-reserve-cancel',`data-id="${r.id}"`)}</div>`).join('')||'<p>예약된 특별실이 없습니다.</p>'}</div>`);}
 function maintenance(){const s=get(),d=Ops.data(s);open('행정실 · 기물 수리 요청',`<p class="intro">고장 난 물품은 사용을 멈추고 행정실에 접수합니다. 부품·방문 일정을 기다린 뒤 수리와 사용 확인을 따로 기록합니다.</p><div class="beta-grid">${field('장소',roomSelect('bm-room',s.room))}${field('물품','<input id="bm-item" placeholder="사물함 문·학생 의자·프로젝터">')}</div>${field('관찰한 상태',text('bm-detail'))}${btn('행정실에 접수','beta-repair-request')}<div class="beta-event-list">${d.maintenance.map(r=>`<div><span><b>${esc(r.item)}</b> · ${M.ROOMS[r.room].name}<small>${esc(r.status)} · 예정 ${M.dateLabel({day:r.readyDay})}</small></span>${btn(({requested:'행정실 일정 회신',scheduled:'수리 완료 확인',repaired:'사용 확인·종결',closed:'종결'})[r.status],'beta-repair-step',`data-id="${r.id}" ${r.status==='closed'?'disabled':''}`)}</div>`).join('')}</div>`);}
 function contests(id){const s=get(),d=Ops.data(s),c=d.competitions.find(x=>x.id===id);if(c){const def=Ops.COMPETITIONS.find(x=>x[0]===c.kind);open(def[1],`<p>${def[3]}</p><p>희망 학생: ${c.members.map(id=>s.students.find(st=>st.id===id).name).join(' · ')}</p><div class="beta-steps">준비·탐구 → 표현·발표 → 돌아보기</div>${field('학생이 실제로 준비·표현·돌아본 내용',text('bt-text'))}${btn(c.step>=3?'과정 공유 완료':['준비 기록 · 20분','발표 기록 · 20분','돌아보기 · 20분'][c.step],'beta-contest-step',`data-id="${id}" ${c.step>=3?'disabled':''}`)}${history(c.records)}${btn('전체 프로젝트','beta-contests')}`);return;}open('학생 대회·탐구 프로젝트',`<p class="intro">학생이 희망한 활동을 과정 중심으로 지원합니다. 수상 여부로 기본 성적을 자동 보정하지 않습니다.</p>${select('bt-kind',Ops.COMPETITIONS.map(c=>[c[0],c[1]+' · '+c[2]]))}<div class="beta-checks">${s.students.map(st=>`<label><input type="checkbox" data-contest-student="${st.id}">${st.name}</label>`).join('')}</div>${btn('희망 학생으로 활동 계획','beta-contest-plan')}<div class="beta-event-list">${d.competitions.map(c=>`<div><span>${Ops.COMPETITIONS.find(x=>x[0]===c.kind)[1]} · ${c.term}학기<small>${c.step}/3단계 · ${c.members.length}명</small></span>${btn('활동 이어가기','beta-contests',`data-id="${c.id}"`)}</div>`).join('')}</div>`);}
 function council(){const s=get(),d=Ops.data(s),e=d.schoolElections.find(x=>x.term===A.term(s));open('전교 선거·학생회',`<p class="intro">학급임원 선거와 전교 선거를 따로 기록합니다. 전교 선거는 전교 명부·희망 후보·선거운동·비밀 투표의 집계를 따로 진행합니다.</p>${btn('전교 후보·선거운동·투표','beta-election-full','','primary')}${btn('우리 반 임원 선거','civics')}<details><summary>이전 버전의 선거 기록</summary><h4>${A.term(s)}학기 전교임원 선거</h4>${e?e.candidates.map(c=>`<div class="beta-dialogue"><b>${c.name}</b><p>${c.promise}</p></div>`).join(''):''}<div class="beta-steps">후보·선거 약속 → 선거운동·공약 읽기 → 투표·결과 확인</div>${btn(e?.stage===3?'이번 학기 결과 확정':['선거 안내 확인 · 10분','선거운동·공약 비교 · 10분','투표 결과 확인 · 10분'][e?.stage||0],'beta-school-election',e?.stage===3?'disabled':'')}${e?.result?`<p>당선: ${e.result.winners.join(' · ')} · ${e.result.candidates.map(c=>c.name+' '+c.votes+'표').join(' / ')}</p>`:''}</details><h4>학급 의견 → 학생회 제안 → 실천 점검</h4>${field('학생들이 모은 의견',text('bu-proposal'))}${btn('제안 전달 · 10분','beta-council-proposal')}${d.council.map(p=>`<article class="beta-card"><b>${esc(p.text)}</b><p>${p.status}</p>${p.followup?`<p>${esc(p.followup)}</p>`:`${text('bu-follow-'+p.id,'','학생들과 실제로 해 본 일과 남은 점')}${btn('실천 결과 확인 · 10분','beta-council-follow',`data-id="${p.id}"`)}`}</article>`).join('')}`);}

 function orders(){const s=get(),d=Ops.data(s);open('준비물 주문·입고·환불',`<p>학습준비물비 잔액 ${s.budget.toLocaleString()}원. 주문 때 예산을 배정하고 실제 입고한 수량만 재고에 추가합니다.</p><div class="beta-grid">${field('물품',select('bo-good',Goods.GOODS.map(g=>[g.id,g.name+' · '+g.cost.toLocaleString()+'원'])))}${field('주문 묶음 수','<input id="bo-qty" type="number" min="1" max="10" value="1">')}</div>${btn('주문하기','beta-order-place')}<p class="intro">일반 지역은 다음 등교일, 산촌은 2일, 섬은 3일 배송을 기다립니다. 미입고 수량만 취소·환불할 수 있습니다.</p>${d.orders.map(o=>`<article class="beta-card"><b>${Goods.getGood(o.itemId).name}</b><p>주문 ${o.quantity} · 입고 ${o.received} · 대기 ${o.remaining} · 환불 ${o.refunded}묶음</p><p>예정 ${M.dateLabel({day:o.due})}</p>${o.remaining?`${field('이번 입고 묶음 수','<input id="bo-receive-'+o.id+'" type="number" min="1" max="'+o.remaining+'" value="1">')}<div class="buttons">${btn('검수 후 부분 입고','beta-order-receive',`data-id="${o.id}"`)}${btn('미입고 취소·환불','beta-order-cancel',`data-id="${o.id}"`)}</div>`:''}${history(o.history)}</article>`).join('')}`);}
 function review(id){const s=get(),d=Review.data(s),report=d.reports.find(r=>r.id===id);if(report){open('행동특성 문장 검토',`<b>${(s.students.find(x=>x.id===report.studentId)?.name||'전출 학생')} · ${report.term}학기</b><p>${report.locked?'확정':'초안'} · 처음 작성 ${report.created}</p><details><summary>선택한 관찰 근거 ${report.evidence.length}개</summary>${history(report.evidence)}</details>${field('검토한 문장',text('bv-text',report.text))}${report.locked?`${field('정정 사유',text('bv-reason'))}${btn('이력을 남기고 정정','beta-review-correct',`data-id="${id}"`)}`:`<div class="buttons">${btn('초안 저장','beta-review-save',`data-id="${id}"`)}${btn('근거 확인·확정','beta-review-lock',`data-id="${id}"`)}</div>`}${btn('기록 검토 목록','beta-review')}`);return;}const st=s.students.find(x=>x.id===val('bv-student'))||s.students[0];open('관찰 근거로 행동특성 검토',`<p class="intro">선택한 행동 누가기록만 연결해 초안을 만듭니다. 개인 메모·배경·친밀도는 가져오지 않습니다. 문장을 검토한 뒤 확정하고, 정정 이력은 보존합니다.</p>${studentSelect('bv-student')}${btn('학생 기록 불러오기','beta-review-load')}<h4>${st.name} · 이번 학년도 관찰</h4>${st.records.map((rec,i)=>rec.kind==='behavior'&&rec.day>=s.academic.start?`<label class="beta-field"><span><input type="checkbox" data-review-index="${i}"> ${esc(rec.date)}</span><p>${esc(rec.text)}</p></label>`:'').join('')||'<p>행동 누가기록을 먼저 입력해 주세요.</p>'}${btn('선택한 근거로 초안','beta-review-draft',`data-id="${st.id}"`)}<h4>검토 중·확정 기록</h4>${d.reports.map(r=>`<div class="beta-row"><span>${(s.students.find(x=>x.id===r.studentId)?.name||'전출 학생')} · ${r.term}학기 ${r.locked?'확정':'초안'}</span>${btn('검토','beta-review',`data-id="${r.id}"`)}</div>`).join('')}${btn('관찰 기록 입력','records')}`);q('bv-student').value=st.id;}
 function show(page,id){({staff,training,support,forms,reservations,maintenance,contests,council,orders,review})[page]?.(id);}
 function handle(action,id,el){const s=get(),page=action.slice(5);if(['staff','training','support','forms','reservations','maintenance','contests','council','orders','review'].includes(page)){show(page,id);return true;}
 if(action==='beta-order-place')outcome(Orders.place(s,val('bo-good'),num('bo-qty')),'orders');
 else if(action==='beta-order-receive')outcome(Orders.receive(s,id,num('bo-receive-'+id)),'orders');
 else if(action==='beta-order-cancel')outcome(Orders.cancel(s,id),'orders');
 else if(action==='beta-review-load')review();
 else if(action==='beta-review-draft')outcome(Review.draft(s,id,[...document.querySelectorAll('[data-review-index]:checked')].map(x=>Number(x.dataset.reviewIndex))),'review');
 else if(action==='beta-review-save'||action==='beta-review-lock')outcome(Review.save(s,id,val('bv-text'),action.endsWith('lock')),'review',id);
 else if(action==='beta-review-correct')outcome(Review.correct(s,id,val('bv-text'),val('bv-reason')),'review',id);
 else if(action==='beta-closure')outcome(Detail.closure(s,num('br-day'),val('br-reason')),'reservations');
 else if(action==='beta-train')outcome(Staff.train(s,id,val('bw-practice')==='1',Number(el.dataset.choice)),'training',id);
 else if(action==='beta-project-plan')outcome(Staff.planProject(s,val('bw-project')),'staff');
 else if(action==='beta-project-share')outcome(Staff.shareProject(s,val('bw-project-report')),'staff');
 else if(action==='beta-audit-step')outcome(Staff.auditStep(s,val('bw-audit')),'staff');
 else if(action==='beta-business-request')outcome(Staff.requestTrip(s,val('bw-trip-title'),num('bw-trip-day'),num('bw-trip-start'),num('bw-trip-end')),'staff');
 else if(action.startsWith('beta-business-'))outcome(Staff.business(s,id,action.slice(14),val('bw-report-'+id)),'staff');
 else if(action==='beta-committee')outcome(Staff.committee(s,val('bw-committee'),val('bw-vote'),val('bw-opinion')),'staff');
 else if(action==='beta-parent-org')outcome(Staff.organize(s,id),'staff');
 else if(action==='beta-social')outcome(Staff.social(s,id),'staff');
 else if(action==='beta-support-open'){const r=Support.open(s,val('bs-student'),val('bs-kind'),val('bs-observation'));outcome(r,'support',r?.id);}
 else if(action==='beta-support-act')outcome(Support.act(s,id,Number(el.dataset.choice),val('bs-note')),'support',id);
 else if(action==='beta-clearance')outcome(Support.clearance(s,id),'support',id);
 else if(action==='beta-doc-submit'){const r=Support.submitDocument(s,{studentId:val('bf-student'),kind:val('bf-kind'),from:num('bf-from'),to:num('bf-to'),channel:val('bf-channel'),absenceType:val('bf-absence'),detail:val('bf-detail'),evidence:val('bf-evidence')});outcome(r,'forms',r?.id);}
 else if(action==='beta-doc-resubmit'){const f=Support.data(s).documents.find(x=>x.id===id);outcome(Support.submitDocument(s,{...f,detail:val('bf-revised'),evidence:val('bf-evidence'),channel:f.channels[0]}),'forms',id);}
 else if(action.startsWith('beta-doc-'))outcome(Support.documentAction(s,id,action.slice(9),val('bf-note')),'forms',id);
 else if(action==='beta-reserve')outcome(Ops.reserve(s,val('br-room'),num('br-day'),num('br-period'),val('br-subject')),'reservations');
 else if(action==='beta-reserve-cancel')outcome(Ops.cancelReservation(s,id),'reservations');
 else if(action==='beta-lesson-change')outcome(Ops.changeLesson(s,num('br-day'),num('br-period'),val('br-subject'),val('br-reason')),'reservations');
 else if(action==='beta-specialist-cover')outcome(Ops.specialistChange(s,num('br-day'),num('br-period'),'cover'),'reservations');
 else if(action==='beta-repair-request')outcome(Ops.maintenance(s,val('bm-room'),val('bm-item'),val('bm-detail')),'maintenance');
 else if(action==='beta-repair-step')outcome(Ops.repairStep(s,id),'maintenance');
 else if(action==='beta-contest-plan'){const ids=[...document.querySelectorAll('[data-contest-student]:checked')].map(x=>x.dataset.contestStudent);outcome(Ops.competition(s,val('bt-kind'),ids),'contests');}
 else if(action==='beta-contest-step')outcome(Ops.contestStep(s,id,val('bt-text')),'contests',id);
 else if(action==='beta-school-election')h.show('election-full');
 else if(action==='beta-council-proposal')outcome(Ops.council(s,val('bu-proposal')),'council');
 else if(action==='beta-council-follow')outcome(Ops.councilFollowup(s,id,val('bu-follow-'+id)),'council');
 else return false;return true;}
 return {show,handle};
}
